WITH `cte` AS (SELECT `srfuzz_mut_1150`.`t_hang`.`k1`, `srfuzz_mut_1150`.`t_hang`.`v1` FROM `srfuzz_mut_1150`.`t_hang`) SELECT count(*) AS `count(*)` FROM (SELECT `cte`.`k1`, `cte`.`v1` FROM `cte` LIMIT 1) `t1` UNION ALL SELECT count(*) AS `count(*)` FROM (SELECT `cte`.`k1`, `cte`.`v1` FROM `cte` LIMIT 1) `t2`;
WITH `cte` AS (SELECT `srfuzz_mut_1150`.`t_hang`.`k1`, `srfuzz_mut_1150`.`t_hang`.`v1` FROM `srfuzz_mut_1150`.`t_hang` LIMIT 200000) SELECT max(`r1`.`cnt`) AS `max(cnt)` FROM (SELECT `cte`.`k1`, count(*) AS `cnt` FROM `cte` GROUP BY `cte`.`k1` ORDER BY `cte`.`k1` ASC  LIMIT 10) `r1` UNION ALL SELECT max(`r2`.`cnt`) AS `max(cnt)` FROM (SELECT `cte`.`v1`, count(*) AS `cnt` FROM `cte` GROUP BY `cte`.`v1` ORDER BY `cte`.`v1` ASC  LIMIT 10) `r2`;